package in.jharkhand.civic.service;
import in.jharkhand.civic.repository.JsonStore; import org.springframework.stereotype.Service; import java.util.*; import java.util.stream.*;
@Service public class DuplicateDetectionService {private final JsonStore s;public DuplicateDetectionService(JsonStore s){this.s=s;} private Set<String> tokens(String x){return Arrays.stream((x==null?"":x).toLowerCase().replaceAll("[^a-z0-9 ]"," ").split("\\s+")).filter(v->v.length()>3).collect(Collectors.toSet());} public Map<String,Object> detect(Map<String,Object> p){Set<String> base=tokens(String.valueOf(p.get("title"))+" "+p.get("description"));List<Map<String,Object>> sims=new ArrayList<>();for(Map<String,Object> q:s.read("problems.json")){if(String.valueOf(q.get("id")).equals(String.valueOf(p.get("id"))))continue;Set<String> other=tokens(String.valueOf(q.get("title"))+" "+q.get("description"));Set<String> inter=new HashSet<>(base);inter.retainAll(other);Set<String> union=new HashSet<>(base);union.addAll(other);double j=union.isEmpty()?0:(double)inter.size()/union.size();if(j>=0.28)sims.add(Map.of("problemId",q.get("id"),"title",q.get("title"),"similarity",Math.round(j*100)/100.0,"locationMatch",sameLocation(p,q)));}sims.sort((a,b)->Double.compare((Double)b.get("similarity"),(Double)a.get("similarity")));return Map.of("isPotentialDuplicate",!sims.isEmpty(),"similarProblems",sims.stream().limit(5).toList(),"confidence",sims.isEmpty()?0:sims.get(0).get("similarity"));} private boolean sameLocation(Map<String,Object>a,Map<String,Object>b){Object la=a.get("location"),lb=b.get("location");return String.valueOf(la).equals(String.valueOf(lb));}}
